pm.test("Status 201 (Created)", function () {
    pm.response.to.have.status(201);
});

// Test 2: Sprawdzenie struktury JSON
pm.test("Zwraca komunikat o dodaniu do bloku", function () {
    const json = pm.response.json();
    pm.expect(json).to.have.property("message");
    pm.expect(json.message).to.include("Transakcja zostanie dodana do bloku");
});

// Test 1: Sprawdzenie kodu odpowiedzi (oczekiwany 200)
pm.test("Status 200 (OK)", function () {
    pm.response.to.have.status(200);
});

// Test 2: Skrót bloku spełnia warunek trudności
pm.test("Skrót bloku spełnia warunek trudności", function () {
    const json = pm.response.json();
    pm.expect(json.hash.startsWith("0000")).to.be.true;
});

// Test 3 (Opcjonalny dla pierwszej iteracji, kluczowy dla kolejnych): Powiązanie bloków
const json = pm.response.json();
const savedHash = pm.environment.get("lastHash");

if (savedHash) {
    pm.test("Zgodność previous_hash z lastHash poprzedniego bloku", function () {
        pm.expect(json.block.previous_hash).to.eql(savedHash);
    });
}

// Zapisanie hasha nowo wydobytego bloku na potrzeby testu w kolejnej iteracji
pm.environment.set("lastHash", json.hash);

pm.test("Status 200 (OK)", function () {
    pm.response.to.have.status(200);
});

pm.test("Zwraca tablice transakcji i jej dlugosc", function () {
    const json = pm.response.json();
    pm.expect(json).to.have.property("transactions");
    pm.expect(json).to.have.property("length");
    pm.expect(json.transactions).to.be.an("array");
    pm.expect(json.transactions.length).to.eql(json.length);
});

pm.test("Status 200 (OK)", function () {
